"""AI Debate visual identity adapted for the intelligence system interface."""

CSS = r"""
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@300;400;500&family=Manrope:wght@400;500;600;700&display=swap');
:root { --bg:#111412; --surface:#181c19; --raised:#202522; --border:#343a35; --text:#e9e9e3; --muted:#909690; --acid:#c7ff37; --orange:#ff6947; --blue:#209dd7; --mono:'DM Mono',monospace; --sans:'Manrope',sans-serif; }
footer,.built-with,.show-api,.api-docs { display:none!important; }
html,body,gradio-app { background:var(--bg)!important; color-scheme:dark; }
body { background-image:linear-gradient(rgb(255 255 255 / 2.5%) 1px,transparent 1px),linear-gradient(90deg,rgb(255 255 255 / 2.5%) 1px,transparent 1px)!important; background-size:42px 42px!important; }
.gradio-container { width:100%!important; max-width:920px!important; min-width:0!important; margin:0 auto!important; padding:34px 24px 48px!important; background:transparent!important; color:var(--text)!important; font-family:var(--sans)!important; }
.gradio-container * { min-width:0; border-radius:0!important; }.block,.form { background:transparent!important; box-shadow:none!important; }
#is-header { display:flex!important; align-items:center!important; gap:28px!important; margin-bottom:2.5rem!important; padding-bottom:1.25rem!important; border-bottom:3px solid var(--text)!important; }
.knowledge-intro { width:100%; max-width:720px; margin:0 0 .25rem 52px; color:var(--muted); font:400 15px/1.65 var(--sans); }.knowledge-intro p { margin:.7rem 0 0!important; }
.intelligence-brand { display:grid; grid-template-columns:auto 1fr; align-items:center; gap:1.4rem; }.intelligence-mark { display:flex; flex-direction:column; gap:5px; width:38px; }.intelligence-bar { display:block; height:7px; }.intelligence-bar-1 { width:100%; background:var(--acid); }.intelligence-bar-2 { width:70%; background:var(--blue); }.intelligence-bar-3 { width:45%; background:var(--orange); }
.intelligence-headings h1 { margin:0!important; color:var(--text)!important; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif!important; font-size:clamp(1.8rem,4vw,2.6rem)!important; font-weight:900!important; line-height:.95!important; letter-spacing:-.045em!important; }.intelligence-sep { margin:0 .04em; color:var(--acid); font-weight:300; }.intelligence-headings p { margin:.55rem 0 0!important; color:var(--muted)!important; font:400 .7rem var(--mono)!important; letter-spacing:.22em; }.is-status { margin-left:auto!important; color:var(--acid)!important; font:400 10px var(--mono)!important; letter-spacing:.08em; text-transform:uppercase; white-space:nowrap; }
#is-chat,#is-inspect { min-height:420px; padding:20px!important; border:1px solid var(--border)!important; background:rgb(24 28 25 / 94%)!important; }#is-chat { box-shadow:18px 18px 0 rgb(0 0 0 / 18%)!important; }#is-inspect h3,#is-ingest h3 { margin:0 0 14px!important; padding-bottom:10px; border-bottom:2px solid var(--acid); color:var(--text)!important; font:500 10px var(--mono)!important; letter-spacing:.13em; text-transform:uppercase; }
textarea,input { min-height:50px!important; padding:13px 14px!important; border:1px solid var(--border)!important; background:var(--surface)!important; color:var(--text)!important; font:400 16px/1.5 var(--sans)!important; }textarea:focus,input:focus { border-color:var(--acid)!important; outline:none!important; box-shadow:0 0 0 1px var(--acid)!important; }button { min-height:50px!important; border:1px solid var(--border)!important; background:var(--surface)!important; color:var(--text)!important; font:500 11px/1.2 var(--mono)!important; letter-spacing:.1em!important; text-transform:uppercase!important; }button.primary,button[variant='primary'] { border-color:var(--acid)!important; background:var(--acid)!important; color:var(--bg)!important; }
.message-row .message,.message-row .message-bubble,.message-row .bubble { font-family:var(--sans)!important; font-size:16px!important; line-height:1.65!important; background:var(--raised)!important; color:var(--text)!important; }.message-row.user-row .message,.message-row[data-role='user'] .message { background:var(--acid)!important; color:var(--bg)!important; }.message-row.bot-row .message,.message-row[data-role='assistant'] .message { border-left:2px solid var(--orange)!important; padding-left:18px!important; }table,th,td { border-color:var(--border)!important; color:var(--text)!important; background:var(--surface)!important; font-family:var(--mono)!important; font-size:11px!important; }
#is-ingest { margin-top:24px; padding:20px!important; border:1px solid var(--border)!important; background:var(--surface)!important; }@media(max-width:700px) { .gradio-container { padding:22px 14px 34px!important; } #is-header { flex-wrap:wrap!important; gap:16px!important; } .is-status { width:100%; margin-left:0!important; } .knowledge-intro { margin-left:0; } #is-chat { box-shadow:8px 8px 0 rgb(0 0 0 / 18%)!important; } }
"""
